// Delay before the attempt following the given (failed) attempt number: the
// initial wait grows by the backoff factor each time and is capped by the
// configured maximum. A zero initial delay always stays zero.
function retryDelay(retry, failedAttempt) {
  const grown = retry.initialDelayMs * (retry.backoffFactor ** (failedAttempt - 1));
  return Math.min(grown, retry.maxDelayMs);
}

// A structured clone of a SharedArrayBuffer — or of a typed array / DataView
// backed by one — succeeds, but the clone keeps sharing the underlying bytes
// with the object the operation implementation holds: mutating those bytes
// later would mutate the value the engine saved, breaking the promise that
// every saved output is an independent copy. Such a return value is therefore
// explicitly unsupported and fails the attempt.
//
// This walks exactly the graph the structured clone algorithm would traverse
// (string-keyed own enumerable properties of plain objects and arrays —
// including non-index properties on arrays — Map keys and values, Set members,
// and Error "cause"), so the rejection is consistent wherever the shared
// memory sits: a bare SharedArrayBuffer, a byte view over one, or bytes nested
// inside objects, arrays, Maps (key or value) or Sets. A plain ArrayBuffer and
// its views are accepted; circular and repeated references are visited once
// via the same identity set the clone would use, so legal graphs' reference
// relationships are unaffected by the check itself.
const VISIBLE_SHARED_MEMORY_TYPES = new Set(['[object Map]', '[object Set]']);

function containsSharedMemory(value) {
  if (value === null || (typeof value !== 'object')) return false;
  const seen = new Set([value]);
  const stack = [value];
  while (stack.length > 0) {
    const current = stack.pop();

    if (current instanceof SharedArrayBuffer) return true;
    // A typed array (Int8Array … BigUint64Array) or a DataView: inspect the
    // buffer it actually reads from. Custom own properties on views are not
    // carried over by structured cloning, so only the backing buffer matters.
    if (ArrayBuffer.isView(current) && current.buffer instanceof SharedArrayBuffer) {
      return true;
    }

    if (Array.isArray(current)) {
      for (const key of Reflect.ownKeys(current)) {
        if (typeof key !== 'string') continue;
        const child = current[key];
        if (child !== null && typeof child === 'object' && !seen.has(child)) {
          seen.add(child);
          stack.push(child);
        }
      }
      continue;
    }

    const tag = Object.prototype.toString.call(current);
    if (tag === '[object Map]') {
      for (const [key, child] of current) {
        if (key !== null && typeof key === 'object' && !seen.has(key)) {
          seen.add(key);
          stack.push(key);
        }
        if (child !== null && typeof child === 'object' && !seen.has(child)) {
          seen.add(child);
          stack.push(child);
        }
      }
      continue;
    }
    if (tag === '[object Set]') {
      for (const member of current) {
        if (member !== null && typeof member === 'object' && !seen.has(member)) {
          seen.add(member);
          stack.push(member);
        }
      }
      continue;
    }
    if (tag === '[object Error]') {
      // Only "cause" survives an Error clone (message/name/stack are copied
      // as primitives; other own properties are dropped), so it alone needs
      // traversal — including when it is non-enumerable.
      if (Object.hasOwn(current, 'cause')) {
        const child = current.cause;
        if (child !== null && typeof child === 'object' && !seen.has(child)) {
          seen.add(child);
          stack.push(child);
        }
      }
      continue;
    }

    // Plain objects (any prototype), Date, RegExp, ArrayBuffer and other
    // structured-cloneable leaf types: only own enumerable string-keyed
    // properties participate in the clone. Symbol-keyed and non-enumerable
    // properties are skipped exactly as structuredClone skips them.
    if (!VISIBLE_SHARED_MEMORY_TYPES.has(tag) && tag !== '[object Error]') {
      for (const key of Object.keys(current)) {
        const child = current[key];
        if (child !== null && typeof child === 'object' && !seen.has(child)) {
          seen.add(child);
          stack.push(child);
        }
      }
    }
  }
  return false;
}

