// Classification uses @@toStringTag rather than `instanceof` so shared buffers
// and views constructed in another realm are recognized. Every possibly
// observable access is guarded: a return value that throws while inspected (a
// revoked proxy, a trap/getter that throws) simply yields the edges that could
// be read, and the structuredClone step that follows reports it in the usual
// way — this check itself never throws.
const SHARED_BUFFER_TAG = '[object SharedArrayBuffer]';
const PLAIN_BUFFER_TAG = '[object ArrayBuffer]';
const MAP_TAG = '[object Map]';
const SET_TAG = '[object Set]';
const ERROR_TAG = '[object Error]';

function containsSharedMemory(value) {
  let rootIsObject;
  try {
    rootIsObject = value !== null && typeof value === 'object';
  } catch {
    // Even `typeof` can throw for a revoked proxy; structuredClone will reject
    // it on its own in the caller.
    return false;
  }
  if (!rootIsObject) return false;

  const seen = new Set();
  const stack = [];

  const pushIfObject = child => {
    let isObject;
    try {
      isObject = child !== null && typeof child === 'object';
    } catch {
      return;
    }
    if (isObject && !seen.has(child)) {
      seen.add(child);
      stack.push(child);
    }
  };
  const tagOf = object => {
    try {
      return Object.prototype.toString.call(object);
    } catch {
      return null;
    }
  };
  const check = (object, constructor) => {
    try {
      return object instanceof constructor;
    } catch {
      return false;
    }
  };

  seen.add(value);
  stack.push(value);

  while (stack.length > 0) {
    const current = stack.pop();
    const tag = tagOf(current);

    if (tag === SHARED_BUFFER_TAG) return true;
    if (tag === PLAIN_BUFFER_TAG) {
      // A plain ArrayBuffer is copied byte-for-byte. Own properties attached
      // to it are dropped by the clone anyway, so nothing needs traversal.
      continue;
    }

    let isView = false;
    try {
      isView = ArrayBuffer.isView(current);
    } catch {
      isView = false;
    }
    if (isView) {
      // A typed array (Int8Array … BigUint64Array) or a DataView: the clone
      // copies only the bytes of its backing buffer — custom own properties
      // on the view are dropped. Shared backing bytes defeat isolation, so a
      // view over a SharedArrayBuffer is rejected; a view over a plain
      // ArrayBuffer is accepted.
      let buffer = null;
      try {
        buffer = current.buffer;
      } catch {
        buffer = null;
      }
      if (buffer !== null && tagOf(buffer) === SHARED_BUFFER_TAG) return true;
      continue;
    }

    let isArray = false;
    try {
      isArray = Array.isArray(current);
    } catch {
      isArray = false;
    }
    if (isArray) {
      // Indexed slots plus enumerable own string-keyed non-index properties,
      // exactly as structuredClone treats arrays.
      let keys;
      try {
        keys = Reflect.ownKeys(current);
      } catch {
        keys = [];
      }
      for (const key of keys) {
        if (typeof key !== 'string') continue;
        let child;
        try {
          child = current[key];
        } catch {
          continue;
        }
        pushIfObject(child);
      }
      continue;
    }

    if (tag === MAP_TAG || check(current, Map)) {
      try {
        for (const [key, child] of current) {
          pushIfObject(key);
          pushIfObject(child);
        }
      } catch {
        // An unreadable iterator exposes nothing else to inspect.
      }
      continue;
    }
    if (tag === SET_TAG || check(current, Set)) {
      try {
        for (const member of current) pushIfObject(member);
      } catch {
        // Ignore an unreadable iterator.
      }
      continue;
    }
    if (tag === ERROR_TAG || check(current, Error)) {
      // Only "cause" survives an Error clone (message/name/stack are copied
      // as primitives; other own properties are dropped), so it alone needs
      // traversal — including when it is non-enumerable.
      let child;
      let present;
      try {
        present = Object.hasOwn(current, 'cause');
        if (present) child = current.cause;
      } catch {
        present = false;
      }
      if (present) pushIfObject(child);
      continue;
    }

    // Plain objects (any prototype), Date, RegExp and other
    // structured-cloneable leaf objects: only own enumerable string-keyed
    // properties participate in the clone. Symbol-keyed and non-enumerable
    // properties are skipped exactly as structuredClone skips them.
    let keys;
    try {
      keys = Object.keys(current);
    } catch {
      continue;
    }
    for (const key of keys) {
      let child;
      try {
        child = current[key];
      } catch {
        continue;
      }
      pushIfObject(child);
    }
  }
  return false;
}

