if (nodeTypes.isTypedArray(current) || nodeTypes.isDataView(current)) {
  // A typed array (Int8Array … BigUint64Array) or a DataView: the clone
  // copies only the bytes of its backing buffer — custom own properties
  // on the view are dropped. Shared backing bytes defeat isolation, so a
  // view over a SharedArrayBuffer is rejected; a view over a plain
  // ArrayBuffer is accepted.
  const [hasBuffer, buffer] = read(current, 'buffer');
  if (hasBuffer && buffer !== null && nodeTypes.isSharedArrayBuffer(buffer)) {
    return true;
  }
  continue;
}

